        "Negative integers are treated as invalid (range error).",
        "Integers greater than current_length are treated as invalid (range error)."
      ],
      "sources": [
        {
          "quote": "at outside 0..current length or a boolean returns {error:'range',operation:index}.",
          "origin": "explicit",
          "interpretation": "Defines the range validation logic."
        }
      ]
    },
    {
      "id": "O4",
      "kind": "postcondition",
      "role": "guarantee",
