      "required": true,
      "scope": [
        "solve"
      ],
      "dependencies": [
        {
          "id": "A1",
          "relation": "assumes"
        }
      ],
      "acceptance_criteria": [
        "A mismatch in any element of the remove sequence triggers a context error.",
        "If len(remove) > current_length - at, a context error is triggered."
      ],
      "sources": [
        {
          "quote": "Otherwise require the full remove sequence to equal current lines starting at at; mismatch or running past EOF returns {error:'context',operation:index}.",
          "origin": "explicit",
          "interpretation": "Defines the context validation logic."
        }
      ]
    },
